svg.metadata:
// The dome's face at height y.
float faceX(float y) { float dy = y - 229.1000; return 548.0 - sqrt(max(0.0, 24964.0 - dy * dy)); }
float field(vec2 p, float t) {
  if (p.x < 24.0 || p.x > 696.0 || p.y < 24.0 || p.y > 436.0) return 0.0;
  float v = 0.0;
  vec2 C = vec2(548.0, 229.1000);
  vec2 d = p - C;
  float r = length(d);
  float cs = d.x / max(r, 1.0);
  float arc = step(cs, 0.34); // the dome covers the side the flood comes from
  float k = floor(p.y / 9.4);
  // the real request: one a cycle, at the flood's own speed on the middle row
  float xr = 40.0 + 490.0 * fract(t / T + 0.8816);
  float ra = sm(40.0, 70.0, xr) * (1.0 - sm(506.0, 530.0, xr));
  // the flood: a row of streaks on every cell from 12 to 38, each row at its own speed (12 to 15 spacings of 35 px a
  // cycle), its pattern repeating over exactly that many spacings so the loop closes; it thickens towards the dome
  if (k > 11.5 && k < 38.5) {
    float n = abs(k - 24.0) < 2.5 ? 14.0 : 12.0 + mod(k * 3.0, 4.0);
    float yr = 9.4 * k + 3.5;
    float fx = faceX(yr);
    float xx = p.x - 35.0 * n * t / T - 35.0 * hash(vec2(k, 7.0));
    float i = floor(xx / 35.0);
    float l = xx - 35.0 * i - 17.5; // from the streak's head
    float xc = p.x - l;
    float thr = 0.3 + 0.45 * pow(abs(k - 25.0) / 14.0, 2.0);
    float there = step(thr, hash(vec2(mod(i, n), k + 3.0)));
    if (abs(k - 24.0) < 2.5) there *= step(34.0, abs(xc - xr)); // the junk is kept off the real request
    // heavier as it nears the dome, where the flood presses on it
    float s = there * sm(40.0, 110.0, xc) * (1.0 - sm(fx - 12.0, fx - 3.0, xc)) * mix(0.8, 1.25, sm(fx - 240.0, fx - 40.0, xc));
    v += s * (0.6 * exp(-l * l / 14.0) + (l < -3.5 && l > -22.0 ? 0.3 - 0.008 * (-3.5 - l) : 0.0));
  }
  // the dome: a dense face that splashes where a streak lands, seamed plates behind it, a faint inner ring, the gate
  if (arc > 0.0) {
    float phi = atan(d.y, -d.x);
    float face = exp(-pow(r - 158.0, 2.0) / 30.0);
    float gate = 1.0 - sm(14.0, 20.0, abs(p.y - 229.1000));
    float pass = exp(-pow((xr - 390.0) / 14.0, 2.0)) * ra;
    v = max(v, face * arc * mix(1.1, 0.42, gate) + face * gate * 0.8 * pass);
    // the splash where the last streak on each nearby row landed, just in front of the face
    for (int o = -1; o <= 1; o++) {
      float kr = k + float(o);
      if (kr < 11.5 || kr > 38.5) continue;
      float n = abs(kr - 24.0) < 2.5 ? 14.0 : 12.0 + mod(kr * 3.0, 4.0);
      float yr = 9.4 * kr + 3.5;
      float hit = faceX(yr) - 7.0; // where a streak goes
      float xf = hit - 35.0 * n * t / T - 35.0 * hash(vec2(kr, 7.0));
      float ih = floor((xf - 17.5) / 35.0) + 1.0; // the first streak past it
      float past = 35.0 * ih + 17.5 - xf;
      float thr = 0.3 + 0.45 * pow(abs(kr - 25.0) / 14.0, 2.0);
      float there = step(thr, hash(vec2(mod(ih, n), kr + 3.0)));
      if (abs(kr - 24.0) < 2.5) there *= step(34.0, abs(hit + past - xr));
      float fl = there * exp(-past * past / 260.0) * arc;
      v = max(v, blob(p, vec2(hit - 2.0, yr), 7.5, 0.95 * fl) + blob(p, vec2(hit - 6.0, yr), 14.0, 0.3 * fl));
    }
    // the gate's posts, a cell above and below the slot
    if ((abs(k - 22.0) < 0.5 || abs(k - 26.0) < 0.5) && r > 136.0 && r < 166.0) v = max(v, 1.1);
    // the plates, seamed every 0.21 rad
    if (r > 136.0 && r < 151.0 && abs(fract(phi / 0.21 + 0.5) - 0.5) < 0.36) v = max(v, mix(0.7, 0.0, gate) * arc);
    // the inner ring
    v = max(v, 0.22 * arc * exp(-pow(r - 127.0, 2.0) / 14.0));
  }
  // the real request: a dense head and a short tail
  v += ra * (blob(p, vec2(xr, 229.1000), 12.0, 1.35) + blob(p, vec2(xr - 19.0, 229.1000), 8.5, 0.6) + blob(p, vec2(xr - 34.0, 229.1000), 6.5, 0.32));
  // the app: a window with a title bar and three lamps, a frame, and lines that light in turn as it answers
  {
    float c = floor((p.x - 4.0) / 7.0 + 0.5);
    if (c > 71.5000 && c < 86.5000 && k > 18.5000 && k < 29.5000) {
      float ta = 0.3306;
      float a = 0.0;
      if (k < 19.5000) {
        bool lamp = abs(c - 73.0) < 0.5 || abs(c - 75.0) < 0.5 || abs(c - 77.0) < 0.5;
        a = lamp ? 0.45 + 0.7 * exp(-pow(t - ta - 0.06, 2.0) / 0.02) : 0.7;
      } else if (c < 72.5000 || c > 85.5000 || k > 28.5000) {
        a = 0.25;
      } else if (mod(k - 19.0, 2.0) < 0.5) {
        float ln = (k - 21.0) / 2.0;
        float len = 5.0 + floor(8.0 * hash(vec2(ln, 4.0)));
        float on = sm(ta + 0.1 + 0.14 * ln, ta + 0.2 + 0.14 * ln, t) * (1.0 - sm(ta + 0.5 + 0.14 * ln, ta + 1.1 + 0.14 * ln, t));
        if (c > 73.5000 && c < 74.5000 + len) a = 0.42 + 0.6 * on;
      }
      v = max(v, a);
    }
  }
  return v;
}
